def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full separator rows and columns divide the grid into panels.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    # The marked symbol is 2; the unmarked panel background is the most
    # frequent other color in the panels.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r0, r1 in row_ranges
        for c0, c1 in col_ranges
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] != 2
    )
    background = counts.most_common(1)[0][0]

    return [
        [
            1 if sum(grid[r][c] == 2
                     for r in range(r0, r1)
                     for c in range(c0, c1)) == 2 else background
            for c0, c1 in col_ranges
        ]
        for r0, r1 in row_ranges
    ]
